/// The SystemGraphService contract: serve the full live observability graph - every
/// component's state, dependencies and counters, plus the snapshot's trace spans - as
/// one typed value. The network-exposed (authenticated) remote-admin surface over the
/// same JSON / CBOR is a later phase; this is the local edge-node observability.
// interface `system-graph` over a channel: opcodes, a Service trait + dispatch, and a Client.
pub mod system_graph {
	use super::*;
	use crate::codec::{Reader, Sink, SliceWriter, Transport, TransportError, VecWriter};
	use alloc::vec::Vec;

	pub const OP_SNAPSHOT: u16 = 1;

	pub trait Service {
		fn snapshot(&mut self) -> Result<Graph, Error>;
	}

	pub fn dispatch<S: Service>(service: &mut S, request: &[u8], request_handles: &mut Handles, out: &mut [u8], reply_handles: &mut Handles) -> Option<usize> {
		let mut reader = Reader::with_handle_list(request, request_handles);
		let r = &mut reader;
		let op = r.u16()?;
		let corr = r.u32()?;
		let mut writer = SliceWriter::new(out);
		if op == PROTOCOL_INFO_OP {
			r.finish()?;
			request_handles.clear();
			let w = &mut writer;
			w.u32(corr)?;
			w.bytes_lp(b"liber:observability")?;
			w.u32(1)?;
			match Handles::try_from_slice(writer.handles()) {
				Some(taken) => *reply_handles = taken,
				None => return None,
			}
			return Some(writer.pos());
		}
		match op {
			OP_SNAPSHOT => {
				r.finish()?;
				request_handles.clear();
				let result = service.snapshot();
				let encoded: Option<()> = (|| {
					let w = &mut writer;
					w.u32(corr)?;
					match &result {
						Ok(v12) => {
							w.u8(1)?;
							v12.write(w)?;
						}
						Err(v13) => {
							w.u8(0)?;
							v13.write(w)?;
						}
					}
					Some(())
				})();
				if encoded.is_none() {
					if writer.has_handle() {
						match Handles::try_from_slice(writer.handles()) {
							Some(taken) => *reply_handles = taken,
							None => {}
						}
						return None;
					}
					// the reply outgrew the caller's buffer: replace it with a typed
					// error, so the client sees a failure instead of hanging.
					writer.reset();
					let w = &mut writer;
					w.u32(corr)?;
					w.u8(0)?;
					Error::Again.write(w)?;
				}
			}
			_ => return None,
		}
		match Handles::try_from_slice(writer.handles()) {
			Some(taken) => *reply_handles = taken,
			None => return None,
		}
		Some(writer.pos())
	}

	fn transport_outcome(error: TransportError) -> Error {
		match error {
			// The request never left this process, so nothing happened and trying
			// again is safe - which is what `again` says.
			TransportError::SendRefused | TransportError::NoRoute => Error::Again,
			// It went out and no answer came back. The server may have acted before
			// it died or before the deadline; nobody knows, and `commit-uncertain` is
			// the answer `base.error` grew so a caller is not forced to guess.
			// The reply could not be held, or arrived and broke the framing rules. In
			// both the server ANSWERED, so it acted; this end simply cannot read what
			// it said, which is the same position as never hearing back.
			TransportError::PeerClosed | TransportError::ReceiveFailed | TransportError::TimedOut | TransportError::NoMemory | TransportError::Malformed => Error::CommitUncertain,
		}
	}

	pub struct Client<T: Transport> {
		transport: T,
		corr: u32,
		deadline: u64,
		last_error: Option<TransportError>,
	}

	impl<T: Transport> Client<T> {
		pub fn new(transport: T) -> Client<T> {
			Client { transport, corr: 0, deadline: 0, last_error: None }
		}
		pub fn with_deadline(transport: T, deadline: u64) -> Client<T> {
			Client { transport, corr: 0, deadline, last_error: None }
		}
		pub fn set_deadline(&mut self, deadline: u64) {
			self.deadline = deadline;
		}
		pub fn last_error(&self) -> Option<TransportError> {
			self.last_error
		}
		pub fn into_transport(self) -> T {
			self.transport
		}
		fn next_corr(&mut self) -> u32 {
			let c = self.corr;
			self.corr = self.corr.wrapping_add(1);
			c
		}
		pub fn protocol_info(&mut self) -> Option<(String, u32)> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(PROTOCOL_INFO_OP)?;
			w.u32(corr)?;
			// No parameter, so no capability: `into_inner` says so rather than this
			// line assuming it.
			let request = writer.into_inner()?;
			let mut reply_handles = Handles::new();
			let reply = self
				.transport
				.call(&request, &[], &mut reply_handles, self.deadline)
				.map_err(|e| {
					self.last_error = Some(e);
					e
				})
				.ok()?;
			if !reply_handles.is_empty() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			let mut reader = Reader::new(&reply);
			let r = &mut reader;
			if r.u32()? != corr {
				return None;
			}
			let package = r.string_lp()?;
			let version = r.u32()?;
			r.finish()?;
			Some((package, version))
		}
		pub fn snapshot(&mut self) -> Option<Result<Graph, Error>> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(OP_SNAPSHOT)?;
			w.u32(corr)?;
			// One call for both halves: the bytes cannot be taken without them.
			let (request, request_handles) = writer.into_message();
			let mut reply_handles = Handles::new();
			let reply = match self.transport.call(&request, request_handles.as_slice(), &mut reply_handles, self.deadline) {
				Ok(reply) => reply,
				Err(e) => {
					self.last_error = Some(e);
					return Some(Err(transport_outcome(e)));
				}
			};
			let mut reader = Reader::with_handle_list(&reply, &reply_handles);
			let decoded = (|| {
				let r = &mut reader;
				if r.u32()? != corr {
					return None;
				}
				let value = if r.tag()? { Ok(Graph::read(r)?) } else { Err(Error::read(r)?) };
				r.finish()?;
				Some(value)
			})();
			if decoded.is_none() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			decoded
		}
	}

	#[cfg(feature = "channel-client-impl")]
	#[inline(never)]
	#[unsafe(export_name = "liber_channel_impl_liber_observability_system_graph_snapshot")]
	fn channel_invoke_snapshot(chan: u64) -> Option<Result<Graph, Error>> {
		let mut client = Client::new(ipc_client::ChannelTransport { chan });
		client.snapshot()
	}
}

/// One component's supervisor state, as the ServiceManager supervisor tracks it: how
/// many times it has been restarted, how many times the watchdog found it hung (alive
/// but unresponsive) and acted, and the kind of its last failure ("" if it has never
/// failed). This is the supervisor's own view - restart counts and failure history a
/// component cannot self-report (a crashed component reports nothing) - which the
/// System Graph folds into each node's counters and the `graph` command renders.
#[derive(Clone, Debug, PartialEq)]
pub struct SupervisorStat {
	pub name: String,
	/// What the supervisor OBSERVES: absent, starting, ready, stopping, stopped or failed. Six
	/// words, and `starting` and `stopping` are the two that had no name - a process that had been
	/// launched and had not reported in used to be called running, which is the one thing it
	/// certainly was not.
	pub state: String,
	/// What the supervisor WANTS: running or stopped. A separate field, because a service somebody
	/// stopped on purpose and one that never came up are otherwise the same observation.
	pub desired: String,
	/// This instance's epoch - the process koid, which the kernel hands out from a counter it
	/// never reuses. A restarted service has a different one, so an endpoint or a report from
	/// before the restart can be recognised as belonging to an instance that has ended.
	pub epoch: u64,
	/// Why the last transition happened. A restart count says how often; this says what for.
	pub last_reason: String,
	pub restarts: u32,
	pub watchdog_trips: u32,
	pub last_failure: String,
}

impl SupervisorStat {
	pub fn encode(&self, out: &mut [u8]) -> Option<usize> {
		let mut w = SliceWriter::new(out);
		self.write(&mut w)?;
		// `finish` refuses while a capability is recorded, because returning the
		// length alone would drop it.
		w.finish()
	}
	pub fn encode_vec(&self) -> Option<Vec<u8>> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		// `into_inner` refuses while a capability is recorded, because returning
		// the bytes alone would drop it.
		w.into_inner()
	}
	pub fn encode_message(&self) -> Option<(Vec<u8>, Handles)> {
		let mut w = VecWriter::new();
		self.write(&mut w)?;
		Some(w.into_message())
	}
	pub fn decode(bytes: &[u8]) -> Option<SupervisorStat> {
		let mut r = Reader::new(bytes);
		let value = SupervisorStat::read(&mut r)?;
		r.finish()?;
		Some(value)
	}
	pub fn decode_message(bytes: &[u8], handles: &mut Handles) -> Option<SupervisorStat> {
		let mut r = Reader::with_handles(bytes, handles);
		let value = SupervisorStat::read(&mut r)?;
		r.finish()?;
		// The frame is good, so the capabilities it carried are the value's now. A
		// refusal above leaves them in the caller's list, which is the half that closes.
		handles.clear();
		Some(value)
	}
	pub fn write<W: Sink>(&self, w: &mut W) -> Option<()> {
		w.bytes_lp(self.name.as_bytes())?;
		w.bytes_lp(self.state.as_bytes())?;
		w.bytes_lp(self.desired.as_bytes())?;
		w.u64(self.epoch)?;
		w.bytes_lp(self.last_reason.as_bytes())?;
		w.u32(self.restarts)?;
		w.u32(self.watchdog_trips)?;
		w.bytes_lp(self.last_failure.as_bytes())?;
		Some(())
	}
	pub fn read(r: &mut Reader) -> Option<SupervisorStat> {
		let name = r.string_lp()?;
		let state = r.string_lp()?;
		let desired = r.string_lp()?;
		let epoch = r.u64()?;
		let last_reason = r.string_lp()?;
		let restarts = r.u32()?;
		let watchdog_trips = r.u32()?;
		let last_failure = r.string_lp()?;
		Some(SupervisorStat { name, state, desired, epoch, last_reason, restarts, watchdog_trips, last_failure })
	}
}

/// The ServiceManager supervisor contract: report the live supervisor state of every
/// managed component - restart counts, watchdog trips and last failure - over the typed
/// API. SystemGraphService queries this and merges it into the live graph, so the
/// observability surface carries the supervisor's history alongside the kernel's live
/// counters. The network-exposed remote-admin surface over the same data is a later phase.
// interface `supervisor` over a channel: opcodes, a Service trait + dispatch, and a Client.
pub mod supervisor {
	use super::*;
	use crate::codec::{Reader, Sink, SliceWriter, Transport, TransportError, VecWriter};
	use alloc::vec::Vec;

	pub const OP_STATUS: u16 = 1;

	pub trait Service {
		fn status(&mut self) -> Result<Vec<SupervisorStat>, Error>;
	}

	pub fn dispatch<S: Service>(service: &mut S, request: &[u8], request_handles: &mut Handles, out: &mut [u8], reply_handles: &mut Handles) -> Option<usize> {
		let mut reader = Reader::with_handle_list(request, request_handles);
		let r = &mut reader;
		let op = r.u16()?;
		let corr = r.u32()?;
		let mut writer = SliceWriter::new(out);
		if op == PROTOCOL_INFO_OP {
			r.finish()?;
			request_handles.clear();
			let w = &mut writer;
			w.u32(corr)?;
			w.bytes_lp(b"liber:observability")?;
			w.u32(1)?;
			match Handles::try_from_slice(writer.handles()) {
				Some(taken) => *reply_handles = taken,
				None => return None,
			}
			return Some(writer.pos());
		}
		match op {
			OP_STATUS => {
				r.finish()?;
				request_handles.clear();
				let result = service.status();
				let encoded: Option<()> = (|| {
					let w = &mut writer;
					w.u32(corr)?;
					match &result {
						Ok(v14) => {
							w.u8(1)?;
							if v14.len() > u16::MAX as usize {
								return None;
							}
							w.u16(v14.len() as u16)?;
							for v16 in v14.iter() {
								v16.write(w)?;
							}
						}
						Err(v15) => {
							w.u8(0)?;
							v15.write(w)?;
						}
					}
					Some(())
				})();
				if encoded.is_none() {
					if writer.has_handle() {
						match Handles::try_from_slice(writer.handles()) {
							Some(taken) => *reply_handles = taken,
							None => {}
						}
						return None;
					}
					// the reply outgrew the caller's buffer: replace it with a typed
					// error, so the client sees a failure instead of hanging.
					writer.reset();
					let w = &mut writer;
					w.u32(corr)?;
					w.u8(0)?;
					Error::Again.write(w)?;
				}
			}
			_ => return None,
		}
		match Handles::try_from_slice(writer.handles()) {
			Some(taken) => *reply_handles = taken,
			None => return None,
		}
		Some(writer.pos())
	}

	fn transport_outcome(error: TransportError) -> Error {
		match error {
			// The request never left this process, so nothing happened and trying
			// again is safe - which is what `again` says.
			TransportError::SendRefused | TransportError::NoRoute => Error::Again,
			// It went out and no answer came back. The server may have acted before
			// it died or before the deadline; nobody knows, and `commit-uncertain` is
			// the answer `base.error` grew so a caller is not forced to guess.
			// The reply could not be held, or arrived and broke the framing rules. In
			// both the server ANSWERED, so it acted; this end simply cannot read what
			// it said, which is the same position as never hearing back.
			TransportError::PeerClosed | TransportError::ReceiveFailed | TransportError::TimedOut | TransportError::NoMemory | TransportError::Malformed => Error::CommitUncertain,
		}
	}

	pub struct Client<T: Transport> {
		transport: T,
		corr: u32,
		deadline: u64,
		last_error: Option<TransportError>,
	}

	impl<T: Transport> Client<T> {
		pub fn new(transport: T) -> Client<T> {
			Client { transport, corr: 0, deadline: 0, last_error: None }
		}
		pub fn with_deadline(transport: T, deadline: u64) -> Client<T> {
			Client { transport, corr: 0, deadline, last_error: None }
		}
		pub fn set_deadline(&mut self, deadline: u64) {
			self.deadline = deadline;
		}
		pub fn last_error(&self) -> Option<TransportError> {
			self.last_error
		}
		pub fn into_transport(self) -> T {
			self.transport
		}
		fn next_corr(&mut self) -> u32 {
			let c = self.corr;
			self.corr = self.corr.wrapping_add(1);
			c
		}
		pub fn protocol_info(&mut self) -> Option<(String, u32)> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(PROTOCOL_INFO_OP)?;
			w.u32(corr)?;
			// No parameter, so no capability: `into_inner` says so rather than this
			// line assuming it.
			let request = writer.into_inner()?;
			let mut reply_handles = Handles::new();
			let reply = self
				.transport
				.call(&request, &[], &mut reply_handles, self.deadline)
				.map_err(|e| {
					self.last_error = Some(e);
					e
				})
				.ok()?;
			if !reply_handles.is_empty() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			let mut reader = Reader::new(&reply);
			let r = &mut reader;
			if r.u32()? != corr {
				return None;
			}
			let package = r.string_lp()?;
			let version = r.u32()?;
			r.finish()?;
			Some((package, version))
		}
		pub fn status(&mut self) -> Option<Result<Vec<SupervisorStat>, Error>> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(OP_STATUS)?;
			w.u32(corr)?;
			// One call for both halves: the bytes cannot be taken without them.
			let (request, request_handles) = writer.into_message();
			let mut reply_handles = Handles::new();
			let reply = match self.transport.call(&request, request_handles.as_slice(), &mut reply_handles, self.deadline) {
				Ok(reply) => reply,
				Err(e) => {
					self.last_error = Some(e);
					return Some(Err(transport_outcome(e)));
				}
			};
			let mut reader = Reader::with_handle_list(&reply, &reply_handles);
			let decoded = (|| {
				let r = &mut reader;
				if r.u32()? != corr {
					return None;
				}
				let value = if r.tag()? {
					Ok({
						let v17 = r.u16()? as usize;
						let mut v18 = Vec::new();
						v18.try_reserve_exact(v17).ok()?;
						for _ in 0..v17 {
							v18.push(SupervisorStat::read(r)?);
						}
						v18
					})
				} else {
					Err(Error::read(r)?)
				};
				r.finish()?;
				Some(value)
			})();
			if decoded.is_none() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			decoded
		}
	}

	#[cfg(feature = "channel-client-impl")]
	#[inline(never)]
	#[unsafe(export_name = "liber_channel_impl_liber_observability_supervisor_status")]
	fn channel_invoke_status(chan: u64) -> Option<Result<Vec<SupervisorStat>, Error>> {
		let mut client = Client::new(ipc_client::ChannelTransport { chan });
		client.status()
	}
}

